    "Starting inventory": "Počáteční inventář",
    "Your first interaction": "Tvoje první interakce",
    "Every map starts with the starting room. Create it with the button on the left.": "Každá mapa začíná startovní místností. Vytvoř ji tlačítkem vlevo.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "Vyber dílek v paletě a polož ho na plán; klávesou R ho otočíš. Prozatím polož dva různé dílky: během hry se vyndají z krabice a připraví.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "Tlačítko Hrdina (H) určuje startovní čtverce našich dobrodruhů. Vyber 2 až 4 čtverce ve startovní místnosti.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "Aby se mapa odhalovala postupně, musíme vytvořit novou místnost. Objeví se při použití objektu, když naprogramujeme spouštěč, který místnost otevře. Zkus to: klikni na tlačítko Objekt (O) a vyber dveře. Pak přidej spouštěč „Otevřít místnost“.",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "Vytvořil jsi svou první interakci s prostředím. Ve hře hrdina otevře dveře a uvolní dílky další místnosti. Teď tu místnost zaplníme: polož truhlu do místnosti a naprogramuj spouštěč, který dá hráčům předměty (ostatní tlačítka a spouštěče na to čekají).",
    "📂 Import a save of the game (.sav)": "📂 Importovat uloženou hru (.sav)",
    "Clear all": "Vymazat vše",
    "Search an item…": "Hledat předmět…",
    "Only what the party has": "Jen to, co družina má",
    "skills": "dovednosti",
    "Others": "Ostatní",
    "Clear the whole starting inventory?": "Vymazat celý počáteční inventář?",
    "Replace the starting inventory with the one of this save?": "Nahradit počáteční inventář tím z této uložené hry?",
    "Imported from the save": "Importováno z uložené hry",
    "This file is not a save of the game.": "Tento soubor není uložená hra.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "Pro družinu veteránů: co už má na začátku kampaně, získané v dřívějších bitvách. Družina to dostane, když kampaň začne. Předměty pocházejí z Dílny (záložky Předměty a Zbraně), dovednosti ze záložky Dovednosti (nebo ze hry). Zásoby předmětů generovaných map vynechávají jedinečné předměty, které družina už má, a hra nikdy nedá předmět dvakrát.",
    "Starting gold": "Počáteční zlato",
