    "The tutorial walks you through the editor step by step. If you ever want to revisit it, you can repeat it from ⚙ Settings.": "Výukový průvodce tě editorem provede krok za krokem. Pokud se k němu budeš chtít vrátit, můžeš ho zopakovat v ⚙ Nastavení.",
    "Yes, skip it": "Ano, přeskočit",
    "Skip the tutorial? Everything unlocks now. If you change your mind, ⚙ Settings can run it again.": "Přeskočit výukového průvodce? Všechno se teď odemkne. Pokud si to rozmyslíš, ⚙ Nastavení ho umí spustit znovu.",
    "Right here!": "Přímo tady!",
    "With Hero (H), click the squares where the heroes start: choose 2 to 4 squares in the starting room.": "Nástrojem Hrdina (H) klikni na čtverce, kde hrdinové začínají: zvol 2 až 4 čtverce ve startovní místnosti.",
    "Nice work!": "Dobrá práce!",
    "The first room is already tied to its door: when a hero opens it, the next room appears on the table. Now let’s add a chest and make it hand out some items to the party. The other buttons and triggers can wait their turn.": "První místnost je už svázaná se svými dveřmi: když je hrdina otevře, na stole se objeví další místnost. Teď přidáme truhlu a necháme ji rozdat družině nějaké předměty. Ostatní tlačítka a spouštěče počkají, až na ně přijde řada.",
    "Place a Chest (Object) in a room, select it and add the “Give or take away an item” trigger. Choose what it gives the party when it is opened.": "Umísti Truhlu (Objekt) do místnosti, vyber ji a přidej spouštěč „Dát nebo vzít předmět“. Zvol, co dá družině, když se otevře.",
    "A brand-new room": "Zbrusu nová místnost",
    "The door came with its script and has already created a new room tied to it. Lay out its tiles whenever you like. Now for some monsters: the Enemy button is unlocked.": "Dveře přišly se svým skriptem a už vytvořily novou místnost, která je na ně navázaná. Rozlož její dílky, kdy budeš chtít. Teď nějaké nestvůry: tlačítko Nepřítel je odemčeno.",
    "Let’s put some monsters in a room: press Enemy (E).": "Dejme do místnosti nějaké nestvůry: stiskni Nepřítel (E).",
    "Ops!": "Jejda!",
    "In the Workshop, press “Import…” and bring in about 10 monsters from the game for this map.": "V Dílně stiskni „Importovat…“ a přines pro tuto mapu asi 10 nestvůr ze hry.",
    "Have a look around the other workshops if you like, then head back to Rooms (◂ Rooms).": "Pokud chceš, porozhlédni se v ostatních dílnách a pak se vrať do Místností (◂ Místnosti).",
    "Now for the room generator. Press ✦ Generate room and click the door that will connect to the new room.": "Teď generátor místností. Stiskni ✦ Generovat místnost a klikni na dveře, které se s novou místností propojí.",
    "First move the room (drag it or use the arrows) or turn it (R). “Use this” becomes available as soon as the room has moved.": "Nejdřív místnost posuň (přetáhni ji nebo použij šipky) nebo ji otoč (R). „Použít tuto“ bude k dispozici, jakmile se místnost pohne.",
    "You have built rooms by hand, programmed objects, brought in monsters, and generated a room. Now only the campaign remains: it connects maps on the world map, with scenes, choices, and rewards between them. Press “Start a campaign” and the rest of the editor opens up.": "Postavil jsi místnosti ručně, naprogramoval objekty, přinesl nestvůry a vygeneroval místnost. Teď zbývá jen kampaň: propojuje mapy na mapě světa, se scénami, volbami a odměnami mezi nimi. Stiskni „Začít kampaň“ a zbytek editoru se otevře.",
    "Press “Start a campaign”: everything is unlocked from there.": "Stiskni „Začít kampaň“: odtud je všechno odemčené.",
    "Explore the story flow, a scene (and its boxes), the starting inventory, and the story variables. Then go back to Rooms (◂ Rooms) to finish.": "Prozkoumej průběh příběhu, scénu (a její okna), počáteční inventář a proměnné příběhu. Pak se vrať do Místností (◂ Místnosti) a dokonči to.",
    "Open the Workshop": "Otevřít Dílnu",
    "Other finer conditions of this feat in the game (first attack of the round, other heroes…) are kept as they are.": "Další jemnější podmínky tohoto činu ve hře (první útok v kole, ostatní hrdinové…) zůstávají, jak jsou.",
    "Otherwise the scene is skipped (the story goes on).": "Jinak se scéna přeskočí (příběh pokračuje).",
    "Pick a box on the left, or add one.": "Vyber okno vlevo, nebo nějaké přidej.",
    "Pick a feat on the left, import one from the game, or write a new one.": "Vyber čin vlevo, importuj ho ze hry, nebo napiš nový.",
    "Pick a kind on the left.": "Vyber druh vlevo.",
    "Pick a recipe on the left, import one from the game, or write a new one.": "Vyber recept vlevo, importuj ho ze hry, nebo napiš nový.",
    "Pick another object": "Vyber jiný objekt",
    "Pillars go in the sockets of an elevated tile of this room at level {n} (the dots on its edges).": "Sloupy patří do patic vyvýšeného dílku této místnosti v patře {n} (tečky na jeho hranách).",
    "Pillars hold up elevated tiles: pick the level of that tile ({n} to {n}) on the ribbon first.": "Sloupy podpírají vyvýšené dílky: nejdřív vyber na pásu karet patro toho dílku ({n} až {n}).",
    "Place the city…": "Umístit město…",
    "Potions and one-use cards the heroes spend during a quest.": "Lektvary a jednorázové karty, které hrdinové během mise spotřebují.",
    "Power of the hero": "Síla hrdiny",
    "Power of the hero (spend to use)": "Síla hrdiny (použitím se vyčerpá)",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms.": "Během hry něco položí na plán nebo z něj vezme: dílky, objekty, nestvůry, místnosti.",
    "Range:": "Dostřel:",
    "Reaches level {n}": "Dosahuje patra {n}",
    "Recipes (the party learns them)": "Recepty (družina se je naučí)",
    "Recipes of the workshop (the party learns it)": "Recepty z Dílny (družina se ho naučí)",
    "Runes of the workshop": "Runy z Dílny",
    "Runes of the workshop (the weapon comes with its rune)": "Runy z Dílny (zbraň přijde se svou runou)",
    "Recovers N health": "Obnoví N zdraví",
    "Remove only that tile": "Odebrat jen ten dílek",
    "Remove the ticked rooms": "Odebrat zaškrtnuté místnosti",
    "Remove what?": "Odebrat co?",
    "Remove whole rooms": "Odebrat celé místnosti",
    "Replace the file…": "Nahradit soubor…",
    "Replace the model…": "Nahradit model…",
    "Replace the music…": "Nahradit hudbu…",
    "Replace the picture…": "Nahradit obrázek…",
