    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "intenzitu místností s nestvůrami a spouštěčů, které volají nestvůry ze zásoby, vše o stejný krok (od −6 do +6, vždy v rozsahu 1 až 10);",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "stupně pro 1–2, 3 a 4 hrdiny u ručně umístěných nestvůr, podle herního pravidla (jako ⚖ Vyvážit u nestvůry).",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "postup kampaně, zásoby nestvůr a předmětů, samotné nestvůry, objekty, spouštěče a texty.",
    "Work out the proposal": "Vypočítat návrh",
    "Simulating…": "Simuluji…",
    "No adjustment does better than the map as it is.": "Žádná úprava nedopadne lépe než mapa tak, jak je.",
