    "Click the marker": "Klikni na značku",
    "Marker (where it goes):": "Značka (kam to jde):",
    "Click the object to move.": "Klikni na objekt, který chceš přesunout.",
    "Click the tile to move (any room).": "Klikni na dílek, který chceš přesunout (v libovolné místnosti).",
    "That one is a marker: click the object itself.": "To je značka: klikni na samotný objekt.",
    "Click a tile (not its marker).": "Klikni na dílek (ne na jeho značku).",
    "Click the object first.": "Nejdřív klikni na objekt.",
    "Click the tile first.": "Nejdřív klikni na dílek.",
    "Click a second object, not the one that moves.": "Klikni na druhý objekt, ne na ten, který se přesouvá.",
    "Click the marker: the same tile laid again, where it goes.": "Klikni na značku: tentýž dílek položený znovu, tam, kam má jít.",
    "Click the marker tile.": "Klikni na dílek-značku.",
    "marker": "značka",
    "Move the tile": "Přesunout dílek",
    "Lays this one as the marker; then click the object whose use moves the tile.": "Položí tento jako značku; pak klikni na objekt, jehož použití dílek přesune.",
    "Remove only that tile, keeping objects and monsters": "Odebrat jen ten dílek, objekty a nestvůry ponechat",
    "(keeps what stands on it)": "(ponechá, co na něm stojí)",
