    "to chain maps on the world map, with scenes, choices and rewards between them.": "a propoj mapy na mapě světa, se scénami, volbami a odměnami mezi nimi.",
    "turn and tilt it with the panel on the board (or Q/E, W/S, right-drag). Esc or the {n}D button returns to the plan.": "otáčej a nakláněj ji panelem na plánu (nebo Q/E, W/S, tažením pravým tlačítkem). Esc nebo tlačítko {n}D vrátí půdorys.",
    "{n}D view": "Pohled {n}D",
    "{n}D view: drag moves the map": "Pohled {n}D: tažení posouvá mapu",
    "{n}D view: drag moves the map; turn and tilt it with the panel on the board (or Q/E, W/S, right-drag). Esc or the {n}D button returns to the plan.": "Pohled {n}D: tažení posouvá mapu; otáčej a nakláněj ji panelem na plánu (nebo Q/E, W/S, tažením pravým tlačítkem). Esc nebo tlačítko {n}D vrátí půdorys.",
    "Campaign started: this map is map {n}. The campaign screen links maps, waypoints and dialogues and places them on the world map.": "Kampaň začala: tato mapa je mapa {n}. Obrazovka kampaně propojuje mapy, body trasy a dialogy a umisťuje je na mapu světa.",
    "From level {n} up a staircase must stand on tiles: put it on tiles of level {n} (only on the floor, level {n}, may it go off the tiles).": "Od patra {n} výš musí schodiště stát na dílcích: polož ho na dílky patra {n} (jen na podlaze, v patře {n}, smí přesahovat mimo dílky).",
    "Quick save done (kept in this browser).": "Rychlé uložení hotovo (uchováno v tomto prohlížeči).",
    "The item pool has no items: add items to it (Workshop → Items, or Map setup).": "Zásoba předmětů nemá žádné předměty: přidej do ní předměty (Dílna → Předměty, nebo Nastavení mapy).",
    "Waypoint added. Place it on the World map tab.": "Bod trasy přidán. Umísti ho na záložce Mapa světa.",
    "they stay hidden until the object is used.": "zůstanou skryté, dokud se objekt nepoužije.",
    "“{q}” opens room {n}. Lay its tiles": "„{Q}“ otevírá místnost {n}. Polož její dílky",
    "“{q}” opens room {n}. Lay its tiles; they stay hidden until the object is used.": "„{Q}“ otevírá místnost {n}. Polož její dílky; zůstanou skryté, dokud se objekt nepoužije.",
    "Answer {n} → end": "Odpověď {n} → konec",
    "Answers": "Odpovědi",
    ". The AppData folder is hidden: paste that path into the address bar of the folder picker.": ". Složka AppData je skrytá: vlož tuto cestu do adresního řádku výběru složky.",
    "Author": "Autor",
    "Author (goes into every map and campaign file you export)": "Autor (zapíše se do každé mapy a souboru kampaně, které exportuješ)",
    "Brings back the hints of Rooms, the explanations shown the first time a tab opens and the warnings you chose not to see again. Reset all settings: tips and warnings, window positions and sizes, author, export folder and autosave. Your maps and campaigns stay.": "Vrátí nápovědy Rooms, vysvětlení zobrazená při prvním otevření záložky a varování, která sis nechal skrýt. Obnovit všechna nastavení: tipy a varování, polohy a velikosti oken, autora, složku exportu a automatické ukládání. Tvoje mapy a kampaně zůstanou.",
    "Choose folder…": "Vybrat složku…",
    "Close": "Zavřít",
    "Copies the Bigorna\\Mapas path": "Zkopíruje cestu Bigorna\\Mapas",
    "Copies the Bigorna\\Mapas path; paste it in Explorer's address bar": "Zkopíruje cestu Bigorna\\Mapas; vlož ji do adresního řádku Průzkumníka",
    "Copy Bigorna\\Mapas path": "Kopírovat cestu Bigorna\\Mapas",
    "Export folder": "Složka exportu",
    "No folder chosen: exported files are downloaded, and the game (with the mod) brings them from Downloads into its maps list by itself. Choosing the folder is only needed for autosave and the list of files.": "Žádná složka nezvolena: exportované soubory se stáhnou a hra (s modem) si je sama přenese ze Stažených souborů do seznamu map. Volba složky je potřeba jen pro automatické ukládání a seznam souborů.",
    "Open a .bmap or .bcamp made with Bigorna Rooms (replaces the current work). Brings chosen rooms of another Bigorna map into this one, without replacing it. Quick save keeps a copy in this browser": "Otevři .bmap nebo .bcamp vytvořený v Bigorna Rooms (nahradí současnou práci). Přenese vybrané místnosti z jiné mapy Bigorna do této a tuto mapu přitom nenahradí. Rychlé uložení uchová kopii v tomto prohlížeči",
    "Open a .bmap or .bcamp made with Bigorna Rooms (replaces the current work). Brings chosen rooms of another Bigorna map into this one, without replacing it. Quick save keeps a copy in this browser; quick load brings it back.": "Otevři .bmap nebo .bcamp vytvořený v Bigorna Rooms (nahradí současnou práci). Přenese vybrané místnosti z jiné mapy Bigorna do této a tuto mapu přitom nenahradí. Rychlé uložení uchová kopii v tomto prohlížeči; rychlé načtení ji vrátí.",
    "Settings": "Nastavení",
    "The maps folder of Descent is": "Složka map Descentu je",
    "Tips and settings": "Tipy a nastavení",
    "Other settings": "Další nastavení",
    "Files in the folder…": "Soubory ve složce…",
    "Files in the folder": "Soubory ve složce",
    "Everything in the folder (maps, campaigns and their folders), with the option to delete": "Vše ve složce (mapy, kampaně a jejich složky), s možností mazání",
    "‹ Back": "‹ Zpět",
    "Refresh": "Obnovit",
    "Delete what you no longer want in the folder: maps (.bmap), campaigns (.bcamp) and their folders. What is deleted here is gone for good.": "Smaž ve složce, co už nechceš: mapy (.bmap), kampaně (.bcamp) a jejich složky. Co tu smažeš, je pryč nadobro.",
    "The browser did not allow reading the folder.": "Prohlížeč nepovolil čtení složky.",
