    "The folder is empty.": "Složka je prázdná.",
    "Work in progress": "Rozpracováno",
    "paste it in Explorer's address bar": "vlož ji do adresního řádku Průzkumníka",
    "quick load brings it back.": "rychlé načtení ji vrátí.",
    "↩ Quick load (F{n})": "↩ Rychlé načtení (F{n})",
    "↺ Show tips and warnings again": "↺ Znovu zobrazit tipy a varování",
    "⇩ Import rooms from a .bmap…": "⇩ Importovat místnosti z .bmap…",
