    "level {n} tall. (P)": "v patře {n} vysoké. (P)",
    "marks the squares where the heroes start, in the starting room ({n} to {n} squares). The players put their figures there before the first room appears.": "označuje čtverce, kde hrdinové začínají, ve startovní místnosti ({n} až {n} čtverců). Hráči tam postaví své figurky, než se objeví první místnost.",
    "same-level tiles cannot overlap. Underlays go under the tiles. (T)": "dílky ve stejném patře se nesmějí překrývat. Podklady jdou pod dílky. (T)",
    "to see the map in relief: elevated tiles, pillars, stairs and ladders.": "a uvidíš mapu v reliéfu: vyvýšené dílky, sloupy, schody a žebříky.",
    "wheel zooms": "kolečko přibližuje",
    "↻ Rotate": "↻ Otočit",
