    "+ Another like this": "+ Další stejný",
    "Balance: sets the tiers for {n}–{n}, {n} and {n} heroes by the game's points (room intensity ÷ {n} × heroes × {n} × progression, shared by the monsters placed in this room), each one above the other": "Vyvážit: nastaví stupně pro {n}–{n}, {n} a {n} hrdiny podle herních bodů (intenzita místnosti ÷ {n} × hrdinové × {n} × postup, rozdělené mezi nestvůry umístěné v této místnosti), každý nad předchozím",
    "Edit in the workshop": "Upravit v Dílně",
    "Like the game's bosses (Levirax: tier {n}, {n} or {n} for {n}, {n} or {n} heroes). The difficulty (Journey, Heroic, Warfare) still applies on top.": "Jako bossové hry (Levirax: stupeň {n}, {n} nebo {n} pro {n}, {n} nebo {n} hrdiny). Obtížnost (Výprava, Hrdinská, Válka) se stále uplatní navrch.",
    "Room intensity": "Intenzita místnosti",
    "Tier": "Stupeň",
    "Tier by the number of heroes": "Stupeň podle počtu hrdinů",
    "Triggers of this monster: they run every time it is defeated, after the game’s own effects (loot, objectives). Taking it off with “{q}” does not count.": "Spouštěče této nestvůry: proběhnou pokaždé, když je poražena, po vlastních efektech hry (kořist, úkoly). Odebrání pomocí „{Q}“ se nepočítá.",
    "When defeated": "Při porážce",
