    "{n} heroes": "{n} hrdinové",
    "{n}–{n} heroes": "{n}–{n} hrdinové",
    "⚖ Balance": "⚖ Vyvážit",
    "Clear the map?": "Vyčistit mapu?",
    "Clear without exporting": "Vyčistit bez exportu",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop, the other maps, the campaign and the author stay. Files already exported stay in the folder.": "Tímto se smažou místnosti ({n}) mapy „{Q}“: dílky, sloupy, objekty, nestvůry, pole hrdinů a jejich spouštěče, a také její název a nastavení mapy (texty, hudba, mise, zásoby, počítadla). Dílna, ostatní mapy, kampaň a autor zůstanou. Už exportované soubory zůstanou ve složce.",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop and the author stay. Files already exported stay in the folder.": "Tímto se smažou místnosti ({n}) mapy „{Q}“: dílky, sloupy, objekty, nestvůry, pole hrdinů a jejich spouštěče, a také její název a nastavení mapy (texty, hudba, mise, zásoby, počítadla). Dílna a autor zůstanou. Už exportované soubory zůstanou ve složce.",
    "The map has nothing to clear.": "Na mapě není co vyčistit.",
    "Do you want to export it before clearing?": "Chceš ji před vyčištěním exportovat?",
    "Everything not exported is lost.": "Vše, co není exportováno, se ztratí.",
    "Export, then clear": "Exportovat a pak vyčistit",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers. The workshop, the map setup (name, texts, music, pools), the other maps and the campaign stay. Files already exported stay in the folder.": "Tímto se smažou místnosti ({n}) mapy „{Q}“: dílky, sloupy, objekty, nestvůry, pole hrdinů a jejich spouštěče. Dílna, nastavení mapy (název, texty, hudba, zásoby), ostatní mapy a kampaň zůstanou. Už exportované soubory zůstanou ve složce.",
    "Writes the .bcamp and its maps (download), then clears.": "Zapíše .bcamp a jeho mapy (stažení) a pak vymaže.",
    "(a hero uses it: tap it with the hero chosen)": "(hrdina ho použije: klepni na něj se zvoleným hrdinou)",
    "(a player taps it with no hero chosen)": "(hráč na něj klepne bez zvoleného hrdiny)",
