    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: tall pillar.": "Zatím žádné: použij nástroj Sloup na jeho patice (patro ${p.level} na pásu karet). Tady povoleno: vysoký sloup.",
