    "Name": "Název",
    "New rooms are born from an object: select it, add the trigger “{q}”. Pick a room here before touching what is in it.": "Nové místnosti se rodí z objektu: vyber ho a přidej spouštěč „{Q}“. Než sáhneš na to, co v ní je, vyber místnost tady.",
