    "What the game would do": "Co by udělala hra",
    "When the group is defeated": "Když je skupina poražena",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "Když místnost začne, hra tato pole zaplní podle svého pravidla pro náhodné objevení: body = intenzita ÷ {n} × hrdinové × {n} × postup; vezme nejvyšší stupeň z rozsahu mapy, na který body stačí (ceny {n}, {n}, {n}, {n}, {n}, {n}…), a nestvůry ze zásoby, které ten stupeň mají, vstoupí, jedna na každé pole (až {n}), dokud body vystačí. Zbylé body přejdou do další vyvážené místnosti. Mohou vstoupit všechny, nebo jen jedna silná nestvůra.",
    "change": "změnit",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "vezme nejvyšší stupeň z rozsahu mapy, na který body stačí (ceny {n}, {n}, {n}, {n}, {n}, {n}…), a nestvůry ze zásoby, které ten stupeň mají, vstoupí, jedna na každé pole (až {n}), dokud body vystačí. Zbylé body přejdou do další vyvážené místnosti. Mohou vstoupit všechny, nebo jen jedna silná nestvůra.",
    "{n} (= spaces, default)": "{n} (= pole, výchozí)",
