    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "Během hry něco položí na plán nebo z něj vezme: dílky, objekty, nestvůry, místnosti. (dílek, objekt, dílek, místnost, objekt, nestvůra)",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "Co se stane jednou, když počet dosáhne {n} (hodnota „Celkem“ počítadla). Několik spouštěčů proběhne postupně.",
    "When the balanced group is defeated: “{q}”": "Když je vyvážená skupina poražena: „{Q}“",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "Cíl na této mapě, oznámený při porážce nestvůry a uvedený mezi úkoly. Úkol mapu neukončí: to udělá mise (Nastavení mapy). Úkol tam lze zvolit jako misi.",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "Od porážky nestvůry spouští počítadlo kol spouštěče uvnitř: každých N kol (tolikrát, kolikrát řekneš, nebo do konce mapy), nebo jednou, o N kol později. Pro vlnu dej dovnitř „{Q}“: objevení má vlastní „{Q}“.",
    "When this monster is defeated: “{q}”": "Když je tato nestvůra poražena: „{Q}“",
    "If the test fails: “{q}”": "Pokud zkouška selže: „{Q}“",
