    ", part": ", část",
    ": part": ": část",
    ": pick a weapon, open one of its parts and change it, or create a new part for one of the three places. The weapon itself only keeps its name.": ": vyber zbraň, otevři jednu z jejích částí a změň ji, nebo vytvoř novou část pro jedno ze tří míst. Samotná zbraň si ponechá jen svůj název.",
    "A change applies while this map is played, to every copy of the part, also the ones bought or found later.": "Změna platí, dokud se tato mapa hraje, pro každou kopii dané části, i pro ty později koupené nebo nalezené.",
    "A different monster each time": "Pokaždé jiná nestvůra",
    "A feat is a goal a hero pursues during the quests (attack with a spear {n} times, open {n} chests…). The game counts it by itself and gives the reward when it is done. Import the game’s feats (they stay as in the game; duplicate one to change it), or write new ones for any hero.": "Čin je cíl, o který hrdina během misí usiluje (zaútočit kopím {n}×, otevřít {n} truhly…). Hra ho počítá sama a po splnění dá odměnu. Importuj činy ze hry (zůstanou jako ve hře; chceš-li některý změnit, zduplikuj ho), nebo napiš nové pro libovolného hrdinu.",
    "A new head of the workshop for this weapon: an item the party gets from a trigger or crafts with a recipe": "Nová hlavice z Dílny pro tuto zbraň: předmět, který družina dostane od spouštěče nebo vyrobí podle receptu",
    "A new weapon in its place": "Nová zbraň na jejím místě",
    "A recipe says what an item costs in crafting materials when the heroes craft it in the camp. Import the game’s recipes to change their costs, or write one for an item of the workshop. The party learns a recipe from a “{q}” trigger, or knows it from the start.": "Recept říká, kolik předmět stojí výrobních surovin, když ho hrdinové vyrábějí v táboře. Importuj recepty ze hry a změň jejich ceny, nebo napiš recept pro předmět z Dílny. Družina se recept naučí ze spouštěče „{Q}“, nebo ho zná od začátku.",
    "A skill card is unlocked for the hero (the physical card at the table)": "Hrdinovi se odemkne karta dovednosti (fyzická karta u stolu)",
    "A skill card is unlocked for the hero (the physical card at the table); a recipe is learned by the party.": "Hrdinovi se odemkne karta dovednosti (fyzická karta u stolu); družina se naučí recept.",
    "A workshop tile is your own physical piece: once per room, reusing it in another room asks to remove the earlier one, and it takes pillars in its sockets (between two squares on a straight edge) when elevated. In the app the mod builds it as a flat tile of this shape, with your picture or colour, and the heroes walk on it like on any tile.": "Dílek z Dílny je tvůj vlastní fyzický díl: jednou v místnosti; jeho použití v jiné místnosti si vyžádá odebrání toho dřívějšího, a když je vyvýšený, bere sloupy do svých patic (mezi dvěma čtverci na rovné hraně). V aplikaci ho mod postaví jako plochý dílek tohoto tvaru, s tvým obrázkem nebo barvou, a hrdinové po něm chodí jako po každém dílku.",
