    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "Šest profilů hry (třída, zbraně, dovednosti a činy) jde do kampaně. Každý hraje hrdina hry (jako ve hře), nebo hrdina z tvé soupisky, zařazený do něj na vlastním listu hrdiny.",
