    "The animated drawing of the game hero of its profile.": "Animovaná kresba hrdiny hry z jeho profilu.",
    "(the profile’s)": "(z profilu)",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "Každá zbraň má ve hře jednoho hrdinu (její části, obchod, inventář a činy jdou s ním). Když vybereš zbraň jiného hrdiny, dostane výměnou tuto. Čísla pocházejí ze zbraní: mění se na záložce Zbraně. Zbraně patří k profilu: zůstanou mu, když hrdina odejde.",
    "The weapons belong to the profile: they stay with it if the hero leaves.": "Zbraně patří k profilu: zůstanou mu, když hrdina odejde.",
    "went back to the roster.": "se vrátil na soupisku.",
