    "Heads, hafts and grips of the weapons, imported in a package or made here: they are in the Weapons tab, under the weapon they belong to.": "Hlavice, násady a rukojeti zbraní, importované v balíčku nebo vytvořené tady: jsou na záložce Zbraně, pod zbraní, ke které patří.",
