    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "Přetahuj díly a sestav zbraň tak, jak ji chceš mít; kolečko (nebo posuvník) mění velikost zvoleného dílu, Shift+kolečko, Q/E nebo posuvník otočení ho otáčí, šipky ho posunou o kousek. Díl se ukazuje jen uvnitř svého rámečku: co z něj vyčnívá, se ořízne (zobrazeno slabě).",
    "Drag the pieces to put the weapon together, forge the template and bake the pictures": "Přetahuj díly, sestav zbraň, ukovej šablonu a vypal obrázky",
    "Duplicate": "Duplikovat",
    "Each sheet changes one of the six heroes of the game while this map is played: name, portrait and animated figure. Their weapons are in the Weapons tab. What you leave as it is stays as in the game.": "Každý list mění jednoho ze šesti hrdinů hry, dokud se tato mapa hraje: jméno, portrét a animovanou figurku. Jejich zbraně jsou na záložce Zbraně. Co necháš, jak je, zůstane jako ve hře.",
