    "Worn by a hero: a card with its rule, kept in the party’s inventory. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Nosí ho hrdina: karta s jeho pravidlem, uložená v inventáři družiny. Spouštěče, odměny a dialogy mohou dávat jen předměty uvedené v Dílně; jen ty mohou padat z nestvůr nebo se vyrábět.",
    "Write plain text. The buttons put in the names the app fills in ([monster] = the name of this monster, [hero] = the name of the hero it targets (or another name the app fills in)) and the game icons. Rule words like scar, terrify or focus become the game’s highlighted terms by themselves.": "Piš prostý text. Tlačítka vloží jména, která aplikace doplní ([monster] = jméno této nestvůry, [hero] = jméno hrdiny, na kterého míří (nebo jiné jméno, které aplikace doplní)), a herní ikony. Pravidlová slova jako jizva, děsit nebo soustředění se sama stanou zvýrazněnými pojmy hry.",
