    "the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "kolečko (nebo posuvník) mění velikost zvoleného dílu, Shift+kolečko, Q/E nebo posuvník otočení ho otáčí, šipky ho posunou o kousek. Díl se ukazuje jen uvnitř svého rámečku: co z něj vyčnívá, se ořízne (zobrazeno slabě).",
    "three parts": "tří částí",
    "tier": "stupeň",
    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the map.": "když je jich příliš málo nebo jsou slabé, hrdinové za nestvůrami zaostanou. Vybírej je záměrně, s ohledem na postup hrdinů během mapy.",
    "turns each piece into a picture of the exact size of its box and puts it in the weapon.": "promění každý díl v obrázek přesné velikosti jeho rámečku a dá ho do zbraně.",
