    "Boxes of text, questions and videos (your own films), played in a row (it goes after the selected card)": "Okna s textem, otázkami a videi (tvými vlastními filmy), přehraná za sebou (přijde za vybranou kartu)",
    "Boxes of “{q}”: drag from a box’s ● (or an answer’s ●) onto another box to say what comes next": "Okna „{Q}“: táhni z ● okna (nebo z ● odpovědi) na jiné okno a urči, co následuje",
    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "Okna se přehrávají v pořadí šipek, od prvního. Okno s otázkou se větví: každá odpověď vede do vlastního dalšího okna. Video okno přehraje tvůj vlastní film (MP{n} nebo WebM) mezi ostatními okny.",
