    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "Každá mapa, vedlejší mise a bod trasy má tady své místo a druh značky: hlavní mise, vedlejší mise, příběhová událost nebo návštěva města.",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "Vše z této kampaně se z editoru smaže a nelze to vrátit zpět:",
