    "Export, then delete": "Exportovat a pak smazat",
    "Files already exported stay in the folder": "Už exportované soubory zůstanou ve složce",
    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "Už exportované soubory zůstanou ve složce; pokud chceš, smaž je tam. Automatické ukládání přestane tuto kampaň sledovat, takže je nesmaže. Hra si ponechá postup každé družiny, která ji hrála.",
    "Fit the whole flow in the view": "Přizpůsobit celý průběh zobrazení",
    "Give crafting materials": "Dát výrobní suroviny",
    "Give the campaign a name (campaign screen).": "Pojmenuj kampaň (obrazovka kampaně).",
    "Happens as": "Nastane jako",
    "It waits for the next visit to the city after the card before it": "Čeká na další návštěvu města po kartě před ní",
    "Lay the cards out left to right": "Rozložit karty zleva doprava",
