    "No remembered choice yet: in a question box, tick “{q}”.": "Zatím žádná zapamatovaná volba: v okně s otázkou zaškrtni „{Q}“.",
    "On the world map as": "Na mapě světa jako",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG nebo JPG, {n}:{n} (přesně sedí {n}×{n}). Pokryje celý rámec, který hra ukazuje",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG nebo JPG, {n}:{n} (přesně sedí {n}×{n}). Pokryje celý rámec, který hra ukazuje; herní voda, spálená země, názvy míst a cesty se skryjí. Mlha pokrývá pevnou oblast herní mapy (Mlžné země).",
    "Place this waypoint on the world map": "Umísti tento bod trasy na mapu světa",
    "Plays as": "Přehraje se jako",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "Najeď na čáru, aby se rozsvítila její šipka. Chceš-li vidět, kam karta vede, klikni na její ●.",
    "Remember a choice": "Zapamatovat volbu",
