    "Simulation": "Simulace",
    "Stay and fill them": "Zůstat a vyplnit je",
    "Story flow": "Průběh příběhu",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "Volby, které si kampaň pamatuje z jedné mapy do další: ušetřený bandita, strana rebelů, vzatý prokletý prsten… Volba se nastaví, když družina zvolí odpověď se zaškrtnutým „{Q}“ (nebo akcí „{Q}“), a platí po zbytek kampaně. Karty průběhu příběhu a spouštěče map se pak mohou uplatnit jen tehdy, když ji družina učinila, nebo naopak neučinila.",
    "The party moves on the world map (it goes after the selected card)": "Družina se pohne po mapě světa (přijde za vybranou kartu)",
    "The scene goes on with the next box when the film ends.": "Když film skončí, scéna pokračuje dalším oknem.",
    "Then:": "Pak:",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "Exportují se, jak jsou. Vyplň je, nebo smaž ty, které nepotřebuješ.",
    "Type the name of the campaign to confirm:": "Pro potvrzení napiš název kampaně:",
    "Unlock a map or waypoint": "Odemknout mapu nebo bod trasy",
    "Use my own city picture…": "Použít vlastní obrázek města…",
