    "World map": "Mapa světa",
    "World map position: -{n}, {n}.": "Poloha na mapě světa: -{n}, {n}.",
    "World map position: {n}, {n}.": "Poloha na mapě světa: {n}, {n}.",
    "Write the boxes of this scene": "Napiš okna této scény",
    "Write the boxes ▸": "Napsat okna ▸",
    "Writes the .bcamp and its maps (download), then deletes.": "Zapíše .bcamp a jeho mapy (stažení) a pak smaže.",
    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "Stavíš místnosti této mapy. Vyber jinou mapu, nebo přidej mapy, body trasy a dialogy na obrazovce kampaně („{Q}“ výše).",
    "after Map {n}": "po Mapě {n}",
    "after Side quest {n}": "po Vedlejší misi {n}",
    "after Waypoint {n}": "po Bodu trasy {n}",
    "after a waypoint it plays on arrival": "po bodu trasy se přehrají po příchodu",
    "arrows nudge the selected card (or the view)": "šipky posunou vybranou kartu (nebo pohled) o kousek",
    "before anything it opens the campaign.": "před vším ostatním otevírají kampaň.",
    "campaign progression {n} (Map setup → Balancing).": "postup kampaně {n} (Nastavení mapy → Vyvážení).",
    "double-click the background adds a box": "dvojklik na pozadí přidá okno",
    "drag from its ● onto another card to link (the target comes after)": "táhni z jejího ● na jinou kartu a propoj je (cíl přichází po ní)",
