    "narrator": "vypravěč",
    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "zatím na ní nic nezávisí: vyber ji v „{Q}“ u karty, nebo jako požadavek „{Q}“ spouštěče mapy.",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "zatím ji nic nenastavuje: zaškrtni „{Q}“ v okně s otázkou a dej jí tento název. Do té doby „{Q}“ nikdy neplatí.",
    "only a question may branch": "větvit se může jen otázka",
    "progression {n}": "postup {n}",
    "question": "otázka",
    "the name is yours.": "název je na tobě.",
    "the scenes that follow it play in the same visit.": "scény, které po ní následují, se přehrají při stejné návštěvě.",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "průběh příběhu: karty: {n}, scény s okny: {n}, proměnné příběhu: {n}",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "Dílna: nestvůry: {n}, NPC: {n}, předměty: {n}, hrdinové: {n}, zbraně: {n}, recepty: {n}, činy: {n}, vlastní dílky/objekty: {n}",
    "the world map positions, the rewards, the music and videos chosen": "polohy na mapě světa, odměny, zvolená hudba a videa",
    "with your own map picture, draw the roads on the left": "s vlastním obrázkem mapy nakresli cesty vlevo",
    "without a name": "bez názvu",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene": "Okna ({n}): text, otázky a videa (tvoje vlastní filmy), přehraná jedno po druhém ve stejném rámci. Přehrají se v tomto bodě příběhu: po mapě je to závěrečná scéna mapy",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "Okna ({n}): text, otázky a videa (tvoje vlastní filmy), přehraná jedno po druhém ve stejném rámci. Přehrají se v tomto bodě příběhu: po mapě je to závěrečná scéna mapy; po bodu trasy se přehrají po příchodu; před vším ostatním otevírají kampaň.",
    "{n} room(s)": "Místnosti: {n}",
    "{n} rooms": "Místnosti: {n}",
    "← Map {n}": "← Mapa {n}",
