    "Original maps": "Původní mapy",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "Původní mapy hry čte mod Bigorna z tvé vlastní kopie hry: jednou spusť hru s nainstalovaným modem (úvodní obrazovka je připraví) a pak znovu otevři editor ze složky Editor ve hře.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "Mise hry převedené na mapy editoru: dílky, objekty, místnosti, nestvůry a logika, kterou spouštěče dokážou vyjádřit.",
    "Each map comes with notes on what was simplified (Map setup).": "Každá mapa přichází s poznámkami o tom, co bylo zjednodušeno (Nastavení mapy).",
