    "🧱 Pieces in your boxes…": "🧱 Díly ve tvých krabicích…",
    "How many of each piece you have: the generators use only these, and the object buttons show how many are on the table while a room is open. A blank field uses the estimate for your boxes (shown faded); ∞ means no limit. Two boxes, or a piece made by hand: raise the number.": "Kolik kusů každého dílu máš: generátory používají jen tyto a tlačítka objektů ukazují, kolik jich je na stole, když je místnost otevřená. Prázdné pole použije odhad pro tvoje krabice (zobrazený vybledle); ∞ znamená bez limitu. Dvě krabice nebo ručně vyrobený díl: zvyš číslo.",
    "3D objects and tokens": "3D objekty a žetony",
    "Pieces in your boxes": "Díly ve tvých krabicích",
    "Piece counts saved.": "Počty dílů uloženy.",
