    "heals every round": "léčí se každé kolo",
    "at full strength": "v plné síle",
    "a hero starts next to a point of interest: it fires at once (warning)": "hrdina začíná vedle zajímavého místa: spustí se hned (varování)",
    "on the table": "na stole",
    "in your boxes": "ve tvých krabicích",
    "points of interest and interaction tokens share the same tokens": "zajímavá místa a žetony interakce sdílejí stejné žetony",
    "More than your boxes hold": "Víc, než obsahují tvoje krabice",
    "🧱 Terrain in your boxes…": "🧱 Terén ve tvých krabicích…",
    "How many pieces of each kind of 3D terrain your boxes hold: the object buttons show how many are on the table.": "Kolik kusů každého druhu 3D terénu tvoje krabice obsahují: tlačítka objektů ukazují, kolik jich je na stole.",
    "Terrain in your boxes": "Terén ve tvých krabicích",
    "Explore / sight tokens": "Žetony průzkumu / výhledu",
    "The rulebooks give 46 terrain pieces in the Act I box and 34 in The Betrayer’s War; the split by kind below is an estimate. Count your own pieces and correct the numbers: the object buttons show how many are on the table while a room is open.": "Pravidla uvádějí 46 kusů terénu v krabici I. dějství a 34 ve Válce zrádce; rozdělení podle druhu níže je odhad. Spočítej své vlastní díly a oprav čísla: tlačítka objektů ukazují, kolik jich je na stole, když je místnost otevřená.",
    "Use the estimate": "Použít odhad",
