    "Change it here: changed, it becomes yours, with the same id (what uses it gets your version; the package’s file stays as it is). To take it out, remove the package (📚 My packages).": "Změň to tady: po změně se to stane tvým, se stejným id (co to používá, dostane tvou verzi; soubor balíčku zůstane, jak je). Chceš-li to odebrat, odeber balíček (📚 Moje balíčky).",
