    "A whole map: why the heroes go in (premise), what they must do to win (objective), what changes along the way (extra rule), how the tension grows and the end. It replaces the map on screen, fully editable.": "Celá mapa: proč hrdinové vstupují (premisa), co musí udělat, aby vyhráli (úkol), co se cestou mění (pravidlo navíc), jak roste napětí a konec. Nahradí mapu na obrazovce a bude plně upravitelná.",
