    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "Tímto se smaže vše, co editor uchovává: mapa nebo kampaň na obrazovce, Dílna (nestvůry, předměty, suroviny, objekty, importované nebo vytvořené), balíčky (v aplikaci: složka Pacotes a každý balíček v ní), obrázky uchované editorem, rychlé uložení, tvoje archetypy, nápovědy a varování, polohy a velikosti oken, autor, složka exportu a automatické ukládání.",
