    "Any health (always counts)": "Libovolné zdraví (počítá se vždy)",
    "Counts only against a monster that has this condition at that moment.": "Počítá se jen proti nestvůře, která má v tu chvíli tento stav.",
    "Counts only against a monster with at least this many conditions at once.": "Počítá se jen proti nestvůře s aspoň tolika stavy najednou.",
