    "Counts only interactions with this kind of object. Without this condition, every object counts except the sight tokens.": "Počítají se jen interakce s tímto druhem objektu. Bez této podmínky se počítá každý objekt kromě žetonů výhledu.",
    "Counts only the items of the ticked kinds.": "Počítají se jen předměty zaškrtnutých druhů.",
    "Counts only when the object leaves the board with the interaction (a chest opened and gone, a token taken, a fire put out).": "Počítá se jen tehdy, když objekt interakcí opustí plán (otevřená a zmizelá truhla, sebraný žeton, uhašený oheň).",
