    "Only the damage that comes from the monster’s weaknesses is added up.": "Sčítá se jen zranění, které pochází ze slabin nestvůry.",
    "Pick the reward": "Vyber odměnu",
    "Reward…": "Odměna…",
    "Skill cards of": "Karty dovedností hrdiny",
    "The damage of each counted attack is added up until it reaches the goal.": "Zranění každého započítaného útoku se sčítá, dokud nedosáhne cíle.",
    "The hero’s health at that moment. “At least” also counts a worse state (a major injury is at least a minor one); “exactly” counts that state only.": "Zdraví hrdiny v tu chvíli. „Aspoň“ počítá i horší stav (těžký úraz je aspoň lehký); „právě“ počítá jen ten stav.",
    "Whether another hero has also attacked this monster.": "Zda na tuto nestvůru zaútočil také jiný hrdina.",
