    "Whether every other hero of the party has already attacked this round.": "Zda každý další hrdina družiny už v tomto kole zaútočil.",
    "Whether some hero has already attacked this round. “Before” counts only the first attack of the round.": "Zda některý hrdina už v tomto kole zaútočil. „Před“ počítá jen první útok kola.",
    "Whether some hero has already interacted this round. “Before” counts only the first interaction of the round.": "Zda některý hrdina už v tomto kole interagoval. „Před“ počítá jen první interakci kola.",
