    "The app changes nothing; the players apply the defense at the table.": "Aplikace nic nemění; hráči uplatní obranu u stolu.",
    "none, the players apply the text at the table": "žádné, hráči uplatní text u stolu",
    "Use the game’s": "Použít ze hry",
    "+ Add to the roll": "+ Přidat k hodu",
    "In the app this weapon is turned {n}°; the boxes show it.": "V aplikaci je tato zbraň otočena o {n}°; rámečky to ukazují.",
    "Click: into the forge · double click: its stats": "Kliknutí: do kovárny · dvojklik: její statistiky",
    "Its stats": "Její statistiky",
    "Its stats (a part of the game: duplicate it to change it)": "Její statistiky (část ze hry: chceš-li ji změnit, zduplikuj ji)",
    "of the game": "ze hry",
    "Pick the parts in the middle column (a double click, or ✎, opens the stats of one). The parts of the game stay as they are; the ones of the workshop move: drag them, the wheel (or the slider) changes the size, Shift+wheel, Q/E or the turn slider rotate, the arrows nudge.": "Vyber části v prostředním sloupci (dvojklik nebo ✎ otevře statistiky jedné z nich). Části ze hry zůstávají, jak jsou; ty z Dílny se pohybují: táhni je, kolečko (nebo posuvník) mění velikost, Shift+kolečko, Q/E nebo posuvník otočení otáčí, šipky posunou o kousek.",
    "keeps each moved piece where it is: its box (where the app draws it) goes with it, and the piece becomes a picture of that box. “Game’s template” undoes what was forged.": "ponechá každý přesunutý díl tam, kde je: jeho rámeček (kde ho aplikace vykreslí) jde s ním a díl se stane obrázkem toho rámečku. „Šablona hry“ vrátí, co bylo ukováno.",
    "A part of the game stays as it is: duplicate it (✎) to move one of your own.": "Část ze hry zůstává, jak je: zduplikuj ji (✎) a přesouvej vlastní.",
    "Back to the game’s template: what was forged is undone.": "Zpět na šablonu hry: co bylo ukováno, je vráceno.",
    "Forged: the parts of the workshop stay where you left them, in the game too.": "Ukováno: části z Dílny zůstanou tam, kde jsi je nechal, i ve hře.",
    "Chance": "Šance",
    "Duplicated: this part is yours to change.": "Zduplikováno: tato část je tvoje a můžeš ji měnit.",
    "+ Box with options": "+ Okno s možnostmi",
    "A box with answers: each one leads to its own next box": "Okno s odpověďmi: každá vede do vlastního dalšího okna",
    "Lay the boxes out left to right, in the order of the arrows": "Rozložit okna zleva doprava, v pořadí šipek",
    "The number the objective and the consequence wait for": "Číslo, na které čekají úkol a důsledek",
    "An objective of the map: completed when the count reaches": "Úkol mapy: splněn, když počet dosáhne",
    "Starts at 0": "Začíná na 0",
    "limit": "limit",
    "Limit": "Limit",
    "The count never goes above this number. Empty: no limit. It always starts at 0.": "Počet nikdy nepřekročí toto číslo. Prázdné: bez limitu. Vždy začíná na 0.",
    "? (no longer in the workshop)": "? (už není v Dílně)",
    "Open it to change it": "Otevři ho a změň ho",
    "Remove this consequence?": "Odebrat tento důsledek?",
    "Counter “{q}” counts rounds by itself: pick the number its objective waits for (Counts button).": "Počítadlo „{Q}“ počítá kola samo: vyber číslo, na které čeká jeho úkol (tlačítko Počty).",
    "Counter “{q}” counts monsters by itself: pick the number its objective waits for (Counts button).": "Počítadlo „{Q}“ počítá nestvůry samo: vyber číslo, na které čeká jeho úkol (tlačítko Počty).",
    "What happens once, when the count reaches {n}. Several triggers run in order.": "Co se stane jednou, když počet dosáhne {n}. Několik spouštěčů proběhne postupně.",
    "the number the counter’s objective waits for (Counts button)": "číslo, na které čeká úkol počítadla (tlačítko Počty)",
    "[count] is the name of the counter (highlighted like the rule words of the game), [n] the count after this trigger, [total] the number its objective waits for (Counts button). Missions and requirements can wait for the counter to reach a number (“{q}”).": "[count] je název počítadla (zvýrazněný jako pravidlová slova hry), [n] počet po tomto spouštěči, [total] číslo, na které čeká jeho úkol (tlačítko Počty). Mise a požadavky mohou čekat, až počítadlo dosáhne určitého čísla („{Q}“).",
    "not in the workshop!": "není v Dílně!",
    "Item…": "Předmět…",
    "original of the game": "originál ze hry",
    "An original of the game: its name, numbers, activations, tactics and defense stay as in the game. Duplicate it (with another name) to make a monster of your own from it. The pictures, the loot and the sounds may change here.": "Originál ze hry: jeho název, čísla, aktivace, taktiky a obrana zůstávají jako ve hře. Chceš-li z něj vytvořit vlastní nestvůru, zduplikuj ho (s jiným názvem). Obrázky, kořist a zvuky se tady mohou změnit.",
    "The figure, animations and behaviour family in the app.": "Figurka, animace a rodina chování v aplikaci.",
    "The order counts:": "Na pořadí záleží:",
    "the monster does its activations in this order (1 first); ↑ ↓ change it. “{q}” chains them. Speed, damage, aim, attack, range, healing, shield, initiative and range type are the numbers the app uses; the text is what the players read.": "nestvůra provádí své aktivace v tomto pořadí (1 první); ↑ ↓ ho mění. „{Q}“ je řetězí. Rychlost, zranění, zaměření, útok, dostřel, léčení, štít, iniciativa a typ dostřelu jsou čísla, která aplikace používá; text je to, co čtou hráči.",
